```python
async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    errors = exc.errors()
    # Convert Decimal to float to make it JSON serializable
    for error in errors:
        if 'ctx' in error and 'limit_value' in error['ctx'] and isinstance(error['ctx']['limit_value'], dict):
            for key, value in error['ctx']['limit_value'].items():
                if isinstance(value, int):
                    error['ctx']['limit_value'][key] = float(value)
        if 'ctx' in error and 'limit_value' in error['ctx']:
            if isinstance(error['ctx']['limit_value'], int):
                error['ctx']['limit_value'] = float(error['ctx']['limit_value'])
    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": errors}
    )
